import csv, sys, collections
from decimal import Decimal as D
sys.stdout.reconfigure(encoding="utf-8")
p = sys.argv[1]
def rows(n): return list(csv.DictReader(open(f"{p}/{n}.csv", encoding="utf-8"), delimiter=";"))
col = {"comissoes_por_lojista": "comissao_brl", "divergencias_taxa": "diferenca_brl", "notas_a_emitir": "valor_brl",
       "lancamentos_classificados": "valor", "pendencias": "valor_brl", "rastro": "valor"}
for n, c in col.items():
    r = rows(n); print(f"{n:30} {len(r):5}  {sum(D(x[c]) for x in r)}")
    if n in ("comissoes_por_lojista", "divergencias_taxa", "notas_a_emitir"):
        g = collections.defaultdict(lambda: [0, D(0)])
        for x in r: g[x["linha_negocio"]][0] += 1; g[x["linha_negocio"]][1] += D(x[c])
        print("   ", dict(g))
    if n == "pendencias": print("   ", collections.Counter(x["tipo"] for x in r))
    if n == "rastro": print("    id_saida:", len({x["id_saida"] for x in r}))
    if n == "lancamentos_classificados": print("   ", collections.Counter(x["metodo"] for x in r))
'@ | Out-File -Encoding utf8 "$s\saida_stats.py"; python -I "$s\saida_stats.py" "$PWD\saida"; git log -1 --format="%h %s" -- saida/

